{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://agentic-qe.dev/schemas/skill-eval.json",
  "title": "AQE Skill Evaluation Test Suite Schema",
  "description": "Schema for skill evaluation YAML test suites used in Trust Tier 3 validation. Supports multi-model testing, AQE MCP integration, and ReasoningBank learning.",
  "type": "object",
  "required": [
    "skill",
    "version",
    "test_cases",
    "success_criteria"
  ],
  "properties": {
    "skill": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9-]*$",
      "description": "Skill name being evaluated (must match .claude/skills/{skill}/SKILL.md)"
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Evaluation suite version (semver)"
    },
    "description": {
      "type": "string",
      "maxLength": 1000,
      "description": "Description of evaluation suite purpose and coverage goals"
    },
    "models_to_test": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "claude-opus-5-5",
          "claude-opus-5",
          "claude-sonnet-5",
          "claude-opus-4-8",
          "claude-opus-4-7",
          "claude-sonnet-4-6",
          "claude-haiku-4-5",
          "claude-opus-4-5",
          "gpt-4o",
          "gpt-4o-mini",
          "gpt-4-turbo"
        ]
      },
      "default": [
        "claude-sonnet-5"
      ],
      "minItems": 1,
      "uniqueItems": true,
      "description": "Models to run evaluation against for cross-model validation"
    },
    "mcp_integration": {
      "$ref": "#/$defs/mcp_integration_config",
      "description": "AQE MCP integration configuration for shared learning"
    },
    "learning": {
      "$ref": "#/$defs/learning_config",
      "description": "ReasoningBank learning configuration"
    },
    "result_format": {
      "$ref": "#/$defs/result_format",
      "description": "Output format configuration"
    },
    "setup": {
      "type": "object",
      "description": "Setup configuration for test environment",
      "properties": {
        "required_tools": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Tools that must be available"
        },
        "environment_variables": {
          "type": "object",
          "additionalProperties": {
            "type": "string"
          },
          "description": "Environment variables to set"
        },
        "fixtures": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string"
              },
              "path": {
                "type": "string"
              },
              "content": {
                "type": "string"
              }
            }
          },
          "description": "Test fixtures to create"
        }
      }
    },
    "test_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/test_case"
      },
      "description": "Evaluation test cases"
    },
    "success_criteria": {
      "type": "object",
      "required": [
        "pass_rate"
      ],
      "properties": {
        "pass_rate": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Minimum pass rate for suite to pass"
        },
        "critical_pass_rate": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "default": 1.0,
          "description": "Pass rate required for critical priority tests"
        },
        "avg_reasoning_quality": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Minimum average reasoning quality score"
        },
        "max_execution_time_ms": {
          "type": "integer",
          "minimum": 0,
          "description": "Maximum execution time for test suite"
        },
        "cross_model_variance": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Maximum allowed variance between models"
        }
      }
    },
    "metadata": {
      "type": "object",
      "properties": {
        "author": {
          "type": "string"
        },
        "created": {
          "type": "string",
          "format": "date"
        },
        "last_updated": {
          "type": "string",
          "format": "date"
        },
        "coverage_target": {
          "type": "string"
        }
      }
    }
  },
  "$defs": {
    "test_case": {
      "type": "object",
      "required": [
        "id",
        "description",
        "input",
        "expected_output"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^tc\\d{3}_[a-z_]+$",
          "description": "Test case ID (e.g., tc001_sql_injection)"
        },
        "description": {
          "type": "string",
          "description": "What this test case validates"
        },
        "category": {
          "type": "string",
          "description": "Test category for grouping"
        },
        "priority": {
          "type": "string",
          "enum": [
            "critical",
            "high",
            "medium",
            "low"
          ],
          "default": "medium",
          "description": "Test priority"
        },
        "skip": {
          "type": "boolean",
          "default": false,
          "description": "Skip this test case"
        },
        "skip_reason": {
          "type": "string",
          "description": "Reason for skipping"
        },
        "input": {
          "$ref": "#/$defs/test_input"
        },
        "expected_output": {
          "$ref": "#/$defs/expected_output"
        },
        "validation": {
          "$ref": "#/$defs/validation_config"
        },
        "timeout_ms": {
          "type": "integer",
          "minimum": 1000,
          "default": 30000,
          "description": "Test timeout in milliseconds"
        },
        "oracle": {
          "$ref": "#/$defs/oracle_config"
        }
      }
    },
    "test_input": {
      "type": "object",
      "description": "Input provided to the skill",
      "properties": {
        "code": {
          "type": "string",
          "description": "Code snippet to analyze"
        },
        "file_path": {
          "type": "string",
          "description": "Path to file to analyze"
        },
        "url": {
          "type": "string",
          "format": "uri",
          "description": "URL to analyze"
        },
        "prompt": {
          "type": "string",
          "description": "Custom prompt for the skill"
        },
        "context": {
          "type": "object",
          "properties": {
            "language": {
              "type": "string",
              "description": "Programming language"
            },
            "framework": {
              "type": "string",
              "description": "Framework in use"
            },
            "environment": {
              "type": "string",
              "enum": [
                "development",
                "staging",
                "production"
              ],
              "description": "Target environment"
            }
          }
        },
        "options": {
          "type": "object",
          "additionalProperties": true,
          "description": "Skill-specific options"
        }
      }
    },
    "expected_output": {
      "type": "object",
      "description": "Expected characteristics of skill output",
      "properties": {
        "must_contain": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Strings that must appear in output"
        },
        "must_not_contain": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Strings that must not appear in output"
        },
        "must_match_regex": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Regex patterns output must match"
        },
        "severity_classification": {
          "type": "string",
          "enum": [
            "critical",
            "high",
            "medium",
            "low",
            "info"
          ],
          "description": "Expected severity classification"
        },
        "finding_count": {
          "type": "object",
          "properties": {
            "min": {
              "type": "integer",
              "minimum": 0
            },
            "max": {
              "type": "integer",
              "minimum": 0
            }
          },
          "description": "Expected range of findings"
        },
        "recommendation_count": {
          "type": "object",
          "properties": {
            "min": {
              "type": "integer",
              "minimum": 0
            },
            "max": {
              "type": "integer",
              "minimum": 0
            }
          },
          "description": "Expected range of recommendations"
        },
        "schema_path": {
          "type": "string",
          "description": "Path to JSON schema for output validation"
        },
        "custom_assertions": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "type": {
                "type": "string",
                "enum": [
                  "jsonpath",
                  "semantic",
                  "function"
                ]
              },
              "expression": {
                "type": "string"
              },
              "expected": {}
            }
          },
          "description": "Custom assertions for complex validation"
        }
      }
    },
    "validation_config": {
      "type": "object",
      "description": "Validation configuration for test case",
      "properties": {
        "schema_check": {
          "type": "boolean",
          "default": true,
          "description": "Validate output against schema"
        },
        "keyword_match_threshold": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "default": 0.8,
          "description": "Minimum keyword match ratio for pass"
        },
        "reasoning_quality_min": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Minimum reasoning quality score"
        },
        "semantic_similarity_min": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Minimum semantic similarity to expected"
        },
        "allow_partial": {
          "type": "boolean",
          "default": false,
          "description": "Allow partial matches"
        },
        "grading_rubric": {
          "type": "object",
          "properties": {
            "completeness": {
              "type": "number",
              "minimum": 0,
              "maximum": 1
            },
            "accuracy": {
              "type": "number",
              "minimum": 0,
              "maximum": 1
            },
            "actionability": {
              "type": "number",
              "minimum": 0,
              "maximum": 1
            }
          },
          "description": "Weighted grading rubric (weights should sum to 1.0)"
        },
        "oracle": {
          "type": "boolean",
          "default": false,
          "description": "Grade this case as an oracle (run+mutate) instead of keyword/semantic matching. Requires test_case.oracle."
        },
        "mutation_score_min": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Minimum mutation kill rate for an oracle case (overrides oracle.threshold when set)"
        }
      }
    },
    "mcp_integration_config": {
      "type": "object",
      "description": "Configuration for AQE MCP tool integration per MCP Integration Spec",
      "properties": {
        "enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable MCP integration for this eval suite"
        },
        "namespace": {
          "type": "string",
          "default": "skill-validation",
          "description": "Memory namespace for storing patterns and outcomes"
        },
        "store_patterns": {
          "type": "boolean",
          "default": true,
          "description": "Store successful patterns via mcp__agentic-qe__memory_store"
        },
        "query_patterns": {
          "type": "boolean",
          "default": true,
          "description": "Query existing patterns before running via mcp__agentic-qe__memory_query"
        },
        "track_outcomes": {
          "type": "boolean",
          "default": true,
          "description": "Track test outcomes via mcp__agentic-qe__test_outcome_track"
        },
        "share_learning": {
          "type": "boolean",
          "default": true,
          "description": "Share learning with fleet via mcp__agentic-qe__memory_share"
        },
        "update_quality_gate": {
          "type": "boolean",
          "default": true,
          "description": "Update quality gate metrics via mcp__agentic-qe__quality_assess"
        },
        "target_agents": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": [
            "qe-learning-coordinator",
            "qe-queen-coordinator"
          ],
          "description": "Agent IDs to share learning with"
        }
      }
    },
    "learning_config": {
      "type": "object",
      "description": "Configuration for ReasoningBank learning integration",
      "properties": {
        "store_success_patterns": {
          "type": "boolean",
          "default": true,
          "description": "Store patterns from successful test runs"
        },
        "store_failure_patterns": {
          "type": "boolean",
          "default": true,
          "description": "Store patterns from failures for learning"
        },
        "pattern_ttl_days": {
          "type": "integer",
          "minimum": 1,
          "maximum": 365,
          "default": 90,
          "description": "Time-to-live for stored patterns in days"
        },
        "min_confidence_to_store": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "default": 0.7,
          "description": "Minimum confidence score to store pattern"
        },
        "cross_model_comparison": {
          "type": "boolean",
          "default": true,
          "description": "Store cross-model behavior comparisons"
        }
      }
    },
    "result_format": {
      "type": "object",
      "description": "Output format configuration for evaluation results",
      "properties": {
        "json_output": {
          "type": "boolean",
          "default": true,
          "description": "Output results as JSON"
        },
        "markdown_report": {
          "type": "boolean",
          "default": false,
          "description": "Generate markdown report"
        },
        "include_raw_output": {
          "type": "boolean",
          "default": false,
          "description": "Include raw LLM output in results"
        },
        "include_timing": {
          "type": "boolean",
          "default": true,
          "description": "Include timing information"
        },
        "include_token_usage": {
          "type": "boolean",
          "default": true,
          "description": "Include token usage statistics"
        }
      }
    },
    "oracle_config": {
      "type": "object",
      "description": "Oracle-mode evaluation: run the skill's generated test against a reference implementation (must pass) and against operator mutants of it (each surviving mutant is a missed bug). Mutation kill rate is the pass signal. Reuses the qe-arena mutator + node --test runner (ADR-104).",
      "required": [
        "module_name",
        "reference_impl"
      ],
      "properties": {
        "module_name": {
          "type": "string",
          "description": "Base name (no extension) of the module under test; the generated test imports it as ../src/<module_name>.mjs"
        },
        "reference_impl": {
          "type": "string",
          "description": "ESM source of the correct implementation the generated test is graded against"
        },
        "max_mutants": {
          "type": "integer",
          "minimum": 1,
          "description": "Cap on mutants evaluated (deterministic position-sorted prefix). Omit to evaluate all."
        },
        "threshold": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "default": 0.5,
          "description": "Minimum mutation kill rate required to pass"
        },
        "extract": {
          "type": "string",
          "enum": [
            "raw",
            "first_code_block"
          ],
          "default": "first_code_block",
          "description": "How to obtain the test source from model output: use it verbatim, or take the first fenced code block"
        }
      }
    }
  }
}

# SPEC-051-A: Agent Booster API Technical Specification

## Overview

This specification documents the Agent Booster API from the `agentic-flow` repository for integration with AQE v3. Agent Booster provides ultra-fast code transformations using a local WASM engine, achieving 352x speedup over cloud APIs at $0 cost.

**Source Repository**: `/tmp/agentic-flow/agentic-flow`

**Key Files**:
- `/tmp/agentic-flow/agentic-flow/src/intelligence/agent-booster-enhanced.ts` - Enhanced Agent Booster v2 with RuVector
- `/tmp/agentic-flow/agentic-flow/src/mcp/tools/agent-booster-tools.ts` - MCP tool definitions
- `/tmp/agentic-flow/agentic-flow/src/optimizations/agent-booster-migration.ts` - Migration utilities

---

## 1. Core Interfaces

### 1.1 EnhancedEditRequest

Input request for code transformation operations.

```typescript
interface EnhancedEditRequest {
  code: string;       // Original source code to transform
  edit: string;       // Target transformed code or transformation instruction
  language: string;   // Programming language (e.g., 'typescript', 'javascript', 'python')
  filePath?: string;  // Optional file path for co-edit tracking
  context?: string;   // Optional additional context
}
```

### 1.2 EnhancedEditResult

Result of a code transformation operation.

```typescript
interface EnhancedEditResult {
  output: string;           // Transformed code
  success: boolean;         // Whether transformation succeeded
  latency: number;          // Execution time in milliseconds
  confidence: number;       // Confidence score (0.0 - 1.0)
  strategy: EditStrategy;   // Strategy used for transformation
  cacheHit: boolean;        // Whether result came from cache
  learned: boolean;         // Whether pattern was learned from this edit
  patternId?: string;       // Pattern identifier if matched
  similarPatterns?: number; // Count of similar patterns found
  fuzzyScore?: number;      // Fuzzy match score (0.0 - 1.0) if fuzzy matched
}

type EditStrategy =
  | 'exact_cache'     // Exact pattern match from cache (0ms)
  | 'fuzzy_match'     // Semantic fuzzy match (1-5ms)
  | 'gnn_match'       // GNN differentiable search
  | 'agent_booster'   // Agent Booster WASM engine
  | 'fallback'        // Traditional method
  | 'error_avoided';  // Error pattern avoidance
```

### 1.3 LearnedPattern

Pattern stored for caching and learning.

```typescript
interface LearnedPattern {
  id: string;                    // Unique pattern identifier
  codeHash: string;              // Hash of original code
  editHash: string;              // Hash of edit/target
  language: string;              // Programming language
  embedding: number[];           // Vector embedding (384-dim)
  confidence: number;            // Current confidence score
  successCount: number;          // Successful applications
  failureCount: number;          // Failed applications
  avgLatency: number;            // Average latency
  lastUsed: number;              // Last used timestamp
  output?: string;               // Cached output
  codeNormalized?: string;       // Normalized code for fuzzy matching
  editType?: string;             // Detected edit type (see Section 2)
  compressed?: boolean;          // Whether embedding is compressed
  accessCount: number;           // Total access count
  createdAt: number;             // Creation timestamp
  compressionTier?: CompressionTier;  // Current compression tier
}

type CompressionTier = 'none' | 'half' | 'pq8' | 'pq4' | 'binary';
```

### 1.4 BoosterStats

Statistics for monitoring and optimization.

```typescript
interface BoosterStats {
  totalEdits: number;          // Total edits processed
  cacheHits: number;           // Exact cache hits
  fuzzyHits: number;           // Fuzzy match hits
  gnnHits: number;             // GNN search hits
  cacheMisses: number;         // Cache misses
  avgLatency: number;          // Average latency (ms)
  avgConfidence: number;       // Average confidence
  patternsLearned: number;     // Total patterns learned
  errorPatternsLearned: number;// Error patterns learned
  sonaUpdates: number;         // SONA learning updates
  gnnSearches: number;         // GNN searches performed
  hitRate: string;             // Cache hit rate percentage
  confidenceImprovement: string; // Confidence improvement percentage
  compressionRatio: string;    // Memory compression ratio
  onnxEnabled: boolean;        // ONNX embeddings status
  tierDistribution: {          // Pattern tier distribution
    hot: number;               // No compression (>0.8 freq)
    warm: number;              // Half compression (>0.4 freq)
    cool: number;              // PQ8 compression (>0.1 freq)
    cold: number;              // PQ4 compression (>0.01 freq)
    archive: number;           // Binary compression (<=0.01 freq)
  };
  totalPatternAccesses: number; // Total pattern accesses
  memorySavings: string;        // Memory savings percentage
}
```

### 1.5 ErrorPattern

Learned error patterns to avoid.

```typescript
interface ErrorPattern {
  pattern: string;        // Normalized pattern string
  errorType: string;      // Type of error
  suggestedFix: string;   // Suggested fix (often original code)
  occurrences: number;    // Number of occurrences
  lastSeen: number;       // Last seen timestamp
}
```

### 1.6 PrefetchResult

Result of prefetch operation for context-aware optimization.

```typescript
interface PrefetchResult {
  file: string;           // File path
  likelyEdits: string[];  // Predicted likely edits
  confidence: number;     // Confidence in predictions
}
```

---

## 2. Supported Transform Types (Edit Types)

The Agent Booster automatically detects and categorizes edit types:

| Edit Type | Description | Example |
|-----------|-------------|---------|
| `var_to_const` | Convert `var` to `const` | `var x = 1;` -> `const x = 1;` |
| `var_to_let` | Convert `var` to `let` | `var x = 1;` -> `let x = 1;` |
| `add_types` | Add TypeScript type annotations | `function foo(x)` -> `function foo(x: any)` |
| `to_async` | Convert `.then()` to async/await | `.then(x => {})` -> `await x` |
| `remove_console` | Remove console statements | `console.log(x);` -> `` |
| `add_async` | Add async keyword to function | `function foo()` -> `async function foo()` |
| `to_esm` | Convert CommonJS to ES modules | `require('x')` -> `import x from 'x'` |
| `general` | General/unclassified transformations | Any other edit |

**Edit Type Detection Logic** (from source):
```typescript
private detectEditType(code: string, edit: string): string {
  if (/\bvar\b/.test(code) && /\bconst\b/.test(edit)) return 'var_to_const';
  if (/\bvar\b/.test(code) && /\blet\b/.test(edit)) return 'var_to_let';
  if (!/:/.test(code) && /:/.test(edit)) return 'add_types';
  if (/\.then\(/.test(code) && /await/.test(edit)) return 'to_async';
  if (/console\./.test(code) && !edit.trim()) return 'remove_console';
  if (/function/.test(code) && /async function/.test(edit)) return 'add_async';
  if (/require\(/.test(code) && /import/.test(edit)) return 'to_esm';
  return 'general';
}
```

---

## 3. API Functions

### 3.1 EnhancedAgentBooster Class

Main class for Agent Booster operations.

```typescript
class EnhancedAgentBooster {
  constructor(options?: {
    storagePath?: string;      // Pattern storage path (default: ~/.agentic-flow/booster-patterns-v2)
    enableOnnx?: boolean;      // Enable ONNX embeddings (default: true)
    enableSona?: boolean;      // Enable SONA learning (default: true)
    maxPatterns?: number;      // Maximum patterns to store (default: 100000)
    fuzzyThreshold?: number;   // Fuzzy match threshold (default: 0.85)
  });

  // Initialize the booster (load patterns, init ONNX)
  async init(): Promise<void>;

  // Apply code transformation
  async apply(request: EnhancedEditRequest): Promise<EnhancedEditResult>;

  // Apply multiple transformations in parallel
  async applyBatch(requests: EnhancedEditRequest[], maxConcurrency?: number): Promise<EnhancedEditResult[]>;

  // Prefetch likely edits for a file
  async prefetch(filePath: string): Promise<PrefetchResult>;

  // Record edit outcome for learning
  async recordOutcome(patternId: string, success: boolean): Promise<void>;

  // Get current statistics
  getStats(): BoosterStats;

  // Persist patterns to disk
  async persist(): Promise<void>;

  // Pretrain with common patterns
  async pretrain(): Promise<{ patterns: number; timeMs: number }>;

  // Force SONA learning cycle
  tick(): string | null;

  // Get intelligence engine statistics
  getIntelligenceStats(): any;

  // Get likely next files to edit
  getLikelyNextFiles(filePath: string, topK?: number): Array<{ file: string; score: number }>;
}
```

### 3.2 Factory Functions

```typescript
// Get singleton enhanced booster instance
function getEnhancedBooster(): EnhancedAgentBooster;

// Quick apply function
async function enhancedApply(
  code: string,
  edit: string,
  language: string
): Promise<EnhancedEditResult>;

// Benchmark enhanced vs baseline
async function benchmark(iterations?: number): Promise<{
  baseline: { avgLatency: number; avgConfidence: number };
  enhanced: { avgLatency: number; avgConfidence: number; cacheHitRate: number; fuzzyHitRate: number };
  improvement: { latency: string; confidence: string };
}>;
```

---

## 4. MCP Tool Definitions

### 4.1 agent_booster_edit_file

Edit a single file using Agent Booster.

**Input Schema**:
```json
{
  "type": "object",
  "properties": {
    "target_filepath": {
      "type": "string",
      "description": "Path of the file to modify"
    },
    "instructions": {
      "type": "string",
      "description": "First-person instruction (e.g., 'I will add error handling')"
    },
    "code_edit": {
      "type": "string",
