    // Superadmin can access everything
    if (user.roles.includes('superadmin')) {
      return true;
    }

    // Define permission matrix
    const permissions: Record<Role, Record<string, string[]>> = {
      user: {
        profile: ['read', 'update'],
        settings: ['read', 'update'],
      },
      moderator: {
