          "description": "Impact of missing index"
        },
        "affectedQueries": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of queries that would benefit"
        },
        "suggestedIndex": {
          "type": "string",
          "description": "SQL to create suggested index"
        }
      }
    },
    "databaseLocation": {
      "type": "object",
      "description": "Location in database",
      "properties": {
        "schema": {
          "type": "string",
