        "table": {
          "type": "string",
          "description": "Table name"
        },
        "column": {
          "type": "string",
          "description": "Column name"
        },
        "constraint": {
          "type": "string",
          "description": "Constraint name"
        },
        "index": {
          "type": "string",
          "description": "Index name"
        },
        "migration": {
          "type": "string",
          "description": "Migration name"
        },
        "file": {
          "type": "string",
